// 1. Relevante Daten vorbereiten
const yesterday = $now.minus({ days: 1 }).toFormat('dd.MM.yyyy');
const currentYear = "2026";
const results = [];

// Das HTML aus der HTML-Node holen
const html = items[0].json.alles;
if (!html) return [{ json: { fehler: "Kein HTML gefunden" } }];

// Wir teilen das HTML in die einzelnen Transfer-Zeilen auf
const rows = html.split('<tr class="');

for (let i = 1; i < rows.length; i++) {
    const row = rows[i];

    // --- BASIS-DATEN EXTRAHIEREN ---
    const dateMatch = row.match(/(\d{2})\.(\d{2})\.(\d{4})/);
    const ligaMatches = [...row.matchAll(/<a title="([^"]*)" href="\/[^"]*\/transfers\/wettbewerb\/[^"]*">/g)];
    const matches = [...row.matchAll(/<td class="hauptlink"><a title="([^"]*)" href="([^"]*)">/g)];

    if (dateMatch && matches.length >= 3) {
        const tag = dateMatch[1];
        const monat = dateMatch[2];
        const jahr = dateMatch[3];
        const gefundenesDatum = `${tag}.${monat}.${jahr}`;
        const ligaName = ligaMatches[0] ? ligaMatches[0][1] : "Unbekannte Liga";

        // --- LOGIK-FILTER ---
        const istJuniorenLiga = ligaName.includes("U19") || ligaName.includes("U17") || ligaName.includes("A-Junioren") || ligaName.includes("B-Junioren");

        let darfInDieMail = false;

        if (istJuniorenLiga) {
            // Für Junioren: Alles aus dem Januar 2026
            if (monat === "01" && jahr === currentYear) {
                darfInDieMail = true;
            }
        } else {
            // Für alle anderen: Nur von gestern
            if (gefundenesDatum === yesterday) {
                darfInDieMail = true;
            }
        }

        // --- DATEN SPEICHERN WENN FILTER PASST ---
        if (darfInDieMail) {
            const baseUrl = "https://www.transfermarkt.de";
            const alterMatch = row.match(/<td class="zentriert">(\d{2})<\/td>/);
            const alter = alterMatch ? alterMatch[1] : "unbekannt";

            results.push({
                json: {
                    spieler: `<a href="${baseUrl}${matches[0][2]}">${matches[0][1]}</a>`,
                    spieler_name_rein: matches[0][1],
                    alter: alter,
                    von_verein: `<a href="${baseUrl}${matches[1][2]}">${matches[1][1]}</a>`,
                    zu_verein: `<a href="${baseUrl}${matches[2][2]}">${matches[2][1]}</a>`,
                    liga: ligaName,
                    datum: gefundenesDatum,
                    info: istJuniorenLiga ? "Junioren-Rückblick" : "Tagesaktuell"
                }
            });
        }
    }
}

if (results.length === 0) {
    return [{ json: { info: "Keine passenden Transfers gefunden." } }];
}

return results;

const finalResults = [];

for (const item of items) {
    const spieler = item.json.spieler;
    const von = item.json.von_verein;
    const zu = item.json.zu_verein;
    const alter = item.json.alter; // Das extrahierte Alter abgreifen

    // WICHTIG: Wir holen die Liga direkt vom Loop-Eingang ab
    const liga = $node["Loop Over Items"].json["Liga"] || "Weitere Transfers";

    // Sicherheitscheck gegen undefined
    const istUngueltig = !spieler || spieler.includes('undefined') || 
                         !von || von.includes('undefined') || 
                         !zu || zu.includes('undefined');

    if (!istUngueltig) {
        // Alter formatieren: Wenn vorhanden, in Klammern setzen
        const alterAnzeige = (alter && alter !== 'unbekannt') ? ` (${alter} Jahre)` : '';

        // Den Satz zusammenbauen: Alter direkt hinter dem Spieler-Link einfügen
        const satz = `Bei ${spieler}${alterAnzeige} hat sich der Vereinsstatus von ${von} zu ${zu} geändert.`;

        finalResults.push({
            json: {
                email_zeile: satz,
                liga: liga,
                datum: item.json.datum
            }
        });
    }
}

return finalResults;

// 1. Alle eingehenden Items holen
const items = $input.all();

// 2. Objekt für die Gruppierung nach Ligen
const transfersNachLigen = {};

for (const item of items) {
  const data = item.json;

  if (data.email_zeile && data.liga) {
    // Wir suchen nach der Zahl in der Klammer innerhalb des Satzes, z.B. "(22 Jahre)"
    const alterMatch = data.email_zeile.match(/\((\d+)\s*Jahre\)/);

    let istJungGenug = false;

    if (alterMatch) {
      // Wenn ein Alter gefunden wurde (z.B. 22), prüfen wir auf <= 23
      const alterZahl = parseInt(alterMatch[1]);
      if (alterZahl <= 23) {
        istJungGenug = true;
      }
    } else {
      // Falls gar kein Alter im Satz steht (keine Klammer gefunden), 
      // lassen wir ihn sicherheitshalber drin (U23-Talente ohne Altersangabe)
      istJungGenug = true;
    }

    // Nur wenn der Spieler jung genug ist, fügen wir ihn der Liste hinzu
    if (istJungGenug) {
      const ligaName = data.liga.trim();

      if (!transfersNachLigen[ligaName]) {
        transfersNachLigen[ligaName] = [];
      }

      transfersNachLigen[ligaName].push(data.email_zeile);
    }
  }
}

// 3. HTML zusammenbauen
let htmlBody = `
<div style="font-family: Arial, sans-serif; line-height: 1.6; color: #333;">
  <p>Guten Morgen Redaktion,</p>
  <p>anbei die Transfers vom gestrigen Tag (Fokus: U23).</p>
`;

const ligenGefunden = Object.keys(transfersNachLigen);

if (ligenGefunden.length === 0) {
  htmlBody += `<p><em>Gestern wurden keine Transferaktivitäten von Spielern bis 23 Jahren registriert.</em></p>`;
} else {
  for (const liga in transfersNachLigen) {
    htmlBody += `
      <h2 style="background-color: #f8f9fa; padding: 8px 12px; border-left: 4px solid #1a3151; margin-top: 25px; font-size: 18px;">
        ${liga}
      </h2>
    `;

    htmlBody += `<ul style="padding-left: 20px; margin-bottom: 20px;">`;

    for (const transferSatz of transfersNachLigen[liga]) {
      htmlBody += `<li style="margin-bottom: 8px;">${transferSatz}</li>`;
    }

    htmlBody += `</ul>`;
  }
}

htmlBody += `
  <p style="margin-top: 30px;">Beste Grüße und bis morgen!</p>
</div>
`;

return {
  htmlMailInhalt: htmlBody
};
